<?php
function finance_chart(): array {return ['1100'=>['Receivables','طلب‌ها','asset'],'1200'=>['Inventory','موجودی اجناس','asset'],'1300'=>['Supplier refunds receivable','طلب برگشت خرید','asset'],'1400'=>['Interbranch clearing','حساب انتقال شعبه‌ها','asset'],'1500'=>['Foreign exchange clearing','حساب واسطهٔ تبدیل ارز','asset'],'2000'=>['Payables','بدهی‌ها','liability'],'2100'=>['Customer refunds payable','بدهی برگشت پول مشتری','liability'],'2900'=>['Unapplied receipts','دریافت تسویه‌نشده','liability'],'3100'=>['Partner profit allocations','تخصیص مفاد شریک','equity'],'3000'=>['Owner capital','سرمایهٔ مالک','equity'],'3900'=>['Opening balance adjustments','تعدیلات ماندهٔ آغاز','equity'],'4100'=>['Exchange gains','مفاد تبدیل ارز','income'],'5300'=>['Exchange losses','ضرر تبدیل ارز','expense'],'4000'=>['Sales revenue','عواید فروش','income'],'4010'=>['Sales returns','برگشت فروش','income'],'5000'=>['Cost of goods sold','بهای جنس فروخته‌شده','expense'],'5100'=>['Operating expenses','مصارف عملیاتی','expense'],'5200'=>['Inventory variances and losses','اختلاف و ضایعات گدام','expense']];}
function finance_date(string $date): string {$d=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date||$date>date('Y-m-d'))throw new InvalidArgumentException(__t('Choose a valid date, not in the future.','تاریخ معتبر و غیرآینده انتخاب کنید.','سمه نېټه وټاکئ.'));return $date;}
function finance_lock(): string {global $pdo;return $pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':'';}
function finance_amount($value,bool $zero=false): string {$v=dec_round($value);if(dec_units($v)<($zero?0:1)||dec_units($v)>100000000000000)throw new InvalidArgumentException('Amount is outside the supported range.');return $v;}
function finance_atomic(callable $fn){global $pdo;$own=!$pdo->inTransaction();if($own)$pdo->beginTransaction();try{$result=$fn();if($own)$pdo->commit();return $result;}catch(Throwable $e){if($own&&$pdo->inTransaction())$pdo->rollBack();throw $e;}}
function finance_seed(int $branch): void {global $pdo;$ins=$pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='sqlite'?'INSERT OR IGNORE':'INSERT IGNORE';foreach(finance_chart() as $code=>[$en,$da,$type])$pdo->prepare("$ins INTO ledger_accounts (shop_id,code,name,account_type) VALUES (?,?,?,?)")->execute([$branch,(string)$code,$en,$type]);$pdo->prepare("$ins INTO financial_periods (shop_id) VALUES (?)")->execute([$branch]);}
function finance_has(string $type,$id,string $currency,?int $branch=null): bool {global $pdo;$q=$pdo->prepare('SELECT id FROM journal_headers WHERE shop_id=? AND source_type=? AND source_id=? AND currency_code=?');$q->execute([$branch??shop_id(),$type,(string)$id,$currency]);return (bool)$q->fetchColumn();}
/** Immutable balanced entries, one currency per document, persisted within source transactions. */
function finance_post(string $type,$id,string $currency,string $date,string $description,array $lines,?int $branch=null): int {
 global $pdo;$branch=$branch??shop_id();$u=auth_user();if(!$u)throw new RuntimeException('Branch access denied.',403);if(!domain_branch_allowed($u,$branch)){
 if($type!=='transfer_out')throw new RuntimeException('Branch access denied.',403);$q=$pdo->prepare("SELECT t.id FROM inventory_transfers t WHERE t.id=? AND t.source_shop_id=? AND t.destination_shop_id=? AND t.status='pending'");$q->execute([(int)$id,$branch,shop_id()]);if(!$q->fetchColumn()||!domain_can('inventory.approve'))throw new RuntimeException('Transfer ledger access denied.',403);$q=$pdo->prepare("SELECT SUM(-value_delta) FROM inventory_movements WHERE shop_id=? AND document_type='transfer_out' AND document_id=? AND currency_code=?");$q->execute([$branch,(string)$id,$currency]);$amount=dec_round($q->fetchColumn());if($lines!==[['1400',$amount,0],['1200',0,$amount]])throw new RuntimeException('Invalid transfer ledger lines.',403);
 }if(!in_array($currency,['AFN','USD','AED','EUR'],true))throw new InvalidArgumentException('Unsupported currency.');finance_date($date);if(!$lines||count($lines)>200)throw new InvalidArgumentException('Invalid journal lines.');
 return finance_atomic(function()use($pdo,$branch,$u,$type,$id,$currency,$date,$description,$lines){finance_seed($branch);$normalized=[];$dr=0;$cr=0;
  foreach($lines as $line){$code=(string)($line[0]??'');$debit=finance_amount($line[1]??0,true);$credit=finance_amount($line[2]??0,true);if((dec_units($debit)>0)===(dec_units($credit)>0))throw new InvalidArgumentException('Each journal row must contain a debit or credit, not both.');$q=$pdo->prepare('SELECT code FROM ledger_accounts WHERE shop_id=? AND code=?');$q->execute([$branch,$code]);if(!$q->fetchColumn())throw new InvalidArgumentException('Unknown branch ledger account.');$q=$pdo->prepare('SELECT currency_code FROM fund_accounts WHERE shop_id=? AND ledger_code=?');$q->execute([$branch,$code]);$fundCurrency=$q->fetchColumn();if($fundCurrency&&in_array($type,['manual','reversal'],true))throw new InvalidArgumentException('Cash and bank movements must use treasury documents.');if($fundCurrency&&$fundCurrency!==$currency)throw new InvalidArgumentException('A cash or bank ledger account cannot use another currency.');$normalized[]=[$code,$debit,$credit];$dr+=dec_units($debit);$cr+=dec_units($credit);}
  if($dr!==$cr||$dr===0)throw new InvalidArgumentException('The journal must balance exactly.');$hash=hash('sha256',json_encode([$currency,$date,$description,$normalized],JSON_THROW_ON_ERROR));
  $q=$pdo->prepare('SELECT id,content_hash FROM journal_headers WHERE shop_id=? AND source_type=? AND source_id=? AND currency_code=?');$q->execute([$branch,$type,(string)$id,$currency]);$existing=$q->fetch();if($existing){if(!hash_equals($existing['content_hash'],$hash))throw new InvalidArgumentException('This source document was already posted with different values.');return (int)$existing['id'];}
  $q=$pdo->prepare('SELECT closed_until FROM financial_periods WHERE shop_id=?'.finance_lock());$q->execute([$branch]);$closed=$q->fetchColumn();if($closed&&$date<=$closed)throw new InvalidArgumentException(__t('This financial period is closed.','این دورهٔ مالی بسته است.','دا مالي دوره تړلې ده.'));
  $pdo->prepare('INSERT INTO journal_headers (shop_id,currency_code,posting_date,source_type,source_id,description,content_hash,created_by) VALUES (?,?,?,?,?,?,?,?)')->execute([$branch,$currency,$date,$type,(string)$id,mb_substr($description,0,1000),$hash,$u['id']]);$jid=(int)$pdo->lastInsertId();foreach($normalized as [$code,$debit,$credit])$pdo->prepare('INSERT INTO journal_details (journal_id,shop_id,account_code,debit,credit) VALUES (?,?,?,?,?)')->execute([$jid,$branch,$code,$debit,$credit]);domain_audit('journal_posted','journal',$jid,['currency'=>$currency,'debit_minor'=>$dr,'credit_minor'=>$cr]);return $jid;
 });
}
function funds_account(int $id,?string $currency=null,bool $lock=false): array {global $pdo;$q=$pdo->prepare("SELECT * FROM fund_accounts WHERE id=? AND shop_id=? AND status='active'".($lock?finance_lock():''));$q->execute([$id,shop_id()]);$row=$q->fetch();if(!$row||($currency!==null&&$row['currency_code']!==$currency))throw new RuntimeException(__t('Select a valid account in this branch and currency.','حساب معتبر همین شعبه و همین ارز را انتخاب کنید.','د همدې څانګې او اسعارو حساب وټاکئ.'),403);return $row;}
function funds_balance(int $id,string $through='9999-12-31'): string {global $pdo;$a=funds_account($id);$q=$pdo->prepare('SELECT COALESCE(SUM(d.debit-d.credit),0) FROM journal_details d JOIN journal_headers h ON h.id=d.journal_id AND h.shop_id=d.shop_id WHERE d.shop_id=? AND d.account_code=? AND h.currency_code=? AND h.posting_date<=?');$q->execute([shop_id(),$a['ledger_code'],$a['currency_code'],$through]);return dec_round($q->fetchColumn());}
/** A backdated payment must leave every later day's recorded balance nonnegative. */
function funds_available_out(int $id,string $date): string {
 global $pdo;$a=funds_account($id);$running=funds_balance($id,$date);$minimum=$running;
 $q=$pdo->prepare('SELECT h.posting_date,SUM(d.debit-d.credit) AS change_amount FROM journal_details d JOIN journal_headers h ON h.id=d.journal_id AND h.shop_id=d.shop_id WHERE d.shop_id=? AND d.account_code=? AND h.currency_code=? AND h.posting_date>? GROUP BY h.posting_date ORDER BY h.posting_date');$q->execute([shop_id(),$a['ledger_code'],$a['currency_code'],$date]);
 foreach($q->fetchAll() as $row){$running=dec_add($running,$row['change_amount']);if(dec_units($running)<dec_units($minimum))$minimum=$running;}return $minimum;
}
function funds_create(string $name,string $kind,string $currency,$opening,?string $request=null): int {
 global $pdo;domain_require('treasury.approve');if(!in_array($kind,['cash','bank'],true)||!in_array($currency,['AFN','USD','AED','EUR'],true)||trim($name)===''||mb_strlen($name)>100)throw new InvalidArgumentException('Invalid fund account.');$opening=finance_amount($opening,true);$request=$request??bin2hex(random_bytes(16));if(!preg_match('/^[a-zA-Z0-9_-]{16,64}$/D',$request))throw new InvalidArgumentException('Invalid account request.');
 return finance_atomic(function()use($pdo,$name,$kind,$currency,$opening,$request){finance_seed(shop_id());$q=$pdo->prepare('SELECT closed_until FROM financial_periods WHERE shop_id=?'.finance_lock());$q->execute([shop_id()]);$q->fetchColumn();$hash=hash('sha256',json_encode([trim($name),$kind,$currency,$opening],JSON_THROW_ON_ERROR));$q=$pdo->prepare('SELECT id,content_hash FROM fund_accounts WHERE shop_id=? AND request_key=?');$q->execute([shop_id(),$request]);if($old=$q->fetch()){if(!hash_equals($old['content_hash'],$hash))throw new InvalidArgumentException('Account request reused with different values.');return (int)$old['id'];}$pdo->prepare('INSERT INTO fund_accounts (shop_id,name,kind,currency_code,request_key,content_hash) VALUES (?,?,?,?,?,?)')->execute([shop_id(),trim($name),$kind,$currency,$request,$hash]);$id=(int)$pdo->lastInsertId();$code='C'.$id;$pdo->prepare("INSERT INTO ledger_accounts (shop_id,code,name,account_type) VALUES (?,?,?,'asset')")->execute([shop_id(),$code,$name]);$pdo->prepare('UPDATE fund_accounts SET ledger_code=? WHERE id=? AND shop_id=?')->execute([$code,$id,shop_id()]);if(dec_units($opening)>0)finance_post('fund_opening',$id,$currency,date('Y-m-d'),'Declared opening balance',[[$code,$opening,0],['3900',0,$opening]]);domain_audit('fund_created','fund_account',$id,['name'=>$name,'currency'=>$currency,'declared_opening'=>$opening]);return $id;});
}
function funds_record(int $account,string $direction,$amount,string $counter,string $source,int $sourceId,string $request,string $date,string $notes=''): int {
 global $pdo;if(!in_array($direction,['in','out'],true)||!preg_match('/^[a-zA-Z0-9_-]{16,64}$/D',$request))throw new InvalidArgumentException('Invalid payment request.');$amount=finance_amount($amount);finance_date($date);
 return finance_atomic(function()use($pdo,$account,$direction,$amount,$counter,$source,$sourceId,$request,$date,$notes){$a=funds_account($account,null,true);$hash=hash('sha256',json_encode([$account,$direction,$amount,$counter,$source,$sourceId,$date,$notes],JSON_THROW_ON_ERROR));$q=$pdo->prepare('SELECT id,content_hash FROM fund_transactions WHERE shop_id=? AND request_key=?');$q->execute([shop_id(),$request]);$old=$q->fetch();if($old){if($old['content_hash']!==$hash)throw new InvalidArgumentException('Payment key reused with different content.');return (int)$old['id'];}
  if($direction==='out'&&dec_units(funds_available_out($account,$date))<dec_units($amount))throw new InvalidArgumentException(__t('Insufficient funds on the payment date or a later recorded day.','در تاریخ پرداخت یا یکی از روزهای بعدی، ماندهٔ حساب کافی نیست.','د تادیې یا ورپسې ورځو پیسې کافي نه دي.'));
  $pdo->prepare('INSERT INTO fund_transactions (shop_id,account_id,direction,amount,currency_code,payment_date,reference,source_type,source_id,request_key,content_hash,notes,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([shop_id(),$account,$direction,$amount,$a['currency_code'],$date,'PAY-'.strtoupper(bin2hex(random_bytes(6))),$source,$sourceId,$request,$hash,mb_substr($notes,0,1000),auth_user()['id']]);$id=(int)$pdo->lastInsertId();$lines=$direction==='in'?[[$a['ledger_code'],$amount,0],[$counter,0,$amount]]:[[$counter,$amount,0],[$a['ledger_code'],0,$amount]];finance_post('fund_payment',$id,$a['currency_code'],$date,$source.' #'.$sourceId,$lines);domain_audit('fund_'.$direction,'payment',$id,['account_id'=>$account,'amount'=>$amount,'currency'=>$a['currency_code'],'source'=>$source,'source_id'=>$sourceId]);return $id;
 });
}
function funds_select(string $name='cash_account_id'): void {global $pdo;$q=$pdo->prepare("SELECT id,name,currency_code FROM fund_accounts WHERE shop_id=? AND status='active' ORDER BY name,id");$q->execute([shop_id()]);echo '<label>'.__t('Cash / bank account (required when money moves)','حساب صندوق یا بانک (هنگام دریافت یا پرداخت لازم است)','د نغدو یا بانک حساب').'<select class="form-control" name="'.sanitize($name).'"><option value="">'.__t('Choose an account','حساب را انتخاب کنید','حساب وټاکئ').'</option>';foreach($q->fetchAll() as $a)echo '<option value="'.(int)$a['id'].'">'.sanitize($a['name'].' · '.$a['currency_code']).'</option>';echo '</select></label>';}
/** Called once by canonical currency persistence, inside the source transaction. */
function finance_currency_event(string $entity,int $id,string $event): void {
 global $pdo;if($event!=='create')return;$date=date('Y-m-d');
 if($entity==='sales'){
  $q=$pdo->prepare('SELECT * FROM sales WHERE id=? AND shop_id=?');$q->execute([$id,shop_id()]);$s=$q->fetch();if(!$s)return;$date=substr($s['created_at'],0,10);$currency=$s['currency_code'];
  if(dec_units($s['total_amount'])>0)finance_post('sale',$id,$currency,$date,'Sales invoice '.$s['invoice_no'],[['1100',$s['total_amount'],0],['4000',0,$s['total_amount']]]);
  $q=$pdo->prepare('SELECT cost_currency_code,SUM(cost_amount) AS cost FROM sale_items WHERE sale_id=? AND shop_id=? GROUP BY cost_currency_code');$q->execute([$id,shop_id()]);foreach($q->fetchAll() as $cost)if(dec_units($cost['cost'])>0)finance_post('sale_cost',$id,$cost['cost_currency_code'],$date,'Cost of sold goods',[['5000',$cost['cost'],0],['1200',0,$cost['cost']]]);
  $received=dec_round($s['paid_amount']);$paymentCurrency=(string)($_POST['payment_currency_code']??$currency);if($paymentCurrency!==$currency)$received=dec_round($_POST['paid_amount']??0);
  if(dec_units($received)>0){$a=funds_account((int)($_POST['cash_account_id']??0),$paymentCurrency);funds_record((int)$a['id'],'in',$received,$paymentCurrency===$currency?'1100':'2900','sale',$id,'sale-receipt-'.$id.'-'.$paymentCurrency,$date,'Invoice receipt');}
  $contracts=$pdo->prepare('SELECT DISTINCT st.mudaraba_id FROM sale_items i JOIN stock st ON st.id=i.stock_id AND st.shop_id=i.shop_id WHERE i.sale_id=? AND i.shop_id=? AND st.mudaraba_id IS NOT NULL');$contracts->execute([$id,shop_id()]);foreach($contracts->fetchAll(PDO::FETCH_COLUMN) as $contract)partner_share_sync((int)$contract,'sale',$id);
 }elseif($entity==='inventory_purchase'){
  $q=$pdo->prepare('SELECT * FROM inventory_purchases WHERE id=? AND shop_id=?');$q->execute([$id,shop_id()]);$s=$q->fetch();if(!$s)return;if(dec_units($s['total_amount'])>0)finance_post('purchase',$id,$s['currency_code'],$s['purchase_date'],'Purchase '.$s['reference'],[['1200',$s['total_amount'],0],['2000',0,$s['total_amount']]]);
  $supplier=(int)($_POST['supplier_id']??0);if($supplier){$q=$pdo->prepare("SELECT id FROM suppliers WHERE id=? AND shop_id=? AND status='active'");$q->execute([$supplier,shop_id()]);if(!$q->fetchColumn())throw new RuntimeException('Supplier unavailable.',403);$pdo->prepare('UPDATE inventory_purchases SET supplier_id=? WHERE id=? AND shop_id=?')->execute([$supplier,$id,shop_id()]);}
 }elseif($entity==='expenses'){
  $q=$pdo->prepare('SELECT * FROM expenses WHERE id=? AND shop_id=?');$q->execute([$id,shop_id()]);$s=$q->fetch();if(!$s||dec_units($s['amount'])<=0)return;
  if(($s['expense_type']??'')==='ضرر'){if(!empty($s['stock_id'])){$sq=$pdo->prepare('SELECT mudaraba_id,partner_id FROM stock WHERE id=? AND shop_id=?'.finance_lock());$sq->execute([$s['stock_id'],shop_id()]);$st=$sq->fetch();if(!empty($st['partner_id']))domain_require('partners.approve');if(!empty($st['mudaraba_id'])){domain_require('mudaraba.approve');if(!partner_account((int)$st['mudaraba_id']))throw new InvalidArgumentException('Review the partnership opening before recording its stock loss.');$pdo->prepare('UPDATE mudaraba_contracts SET profit_known=0 WHERE id=? AND shop_id=?')->execute([$st['mudaraba_id'],shop_id()]);domain_audit('partner_loss_review_required','mudaraba',$st['mudaraba_id'],['loss_id'=>$id]);}}$linked=!empty($s['stock_id'])&&$s['inventory_cost']!==null;$amount=$linked?dec_round($s['inventory_cost']):dec_round($s['amount']);$currency=$linked?$s['inventory_currency_code']:$s['currency_code'];finance_post('loss',$id,$currency,$s['expense_date']?:$date,'Inventory loss',[['5200',$amount,0],[$linked?'1200':'3900',0,$amount]]);if($linked)inventory_movement((int)$s['stock_id'],'loss',$id,'-'.$s['loss_qty'],'-'.$amount,$currency);return;}
  $account=(int)($_POST['cash_account_id']??0);if($account){$a=funds_account($account,$s['currency_code']);funds_record($account,'out',$s['amount'],'5100','expense',$id,'expense-payment-'.$id,$s['expense_date']?:$date,$s['description']??'');}else finance_post('expense_payable',$id,$s['currency_code'],$s['expense_date']?:$date,'Unpaid operating expense',[['5100',$s['amount'],0],['2000',0,$s['amount']]]);
 }elseif($entity==='capital'&&($_POST['action']??'')==='add_capital'){
  $q=$pdo->prepare('SELECT * FROM capital WHERE id=? AND shop_id=?');$q->execute([$id,shop_id()]);$s=$q->fetch();if($s&&dec_units($s['amount'])>0){$a=funds_account((int)($_POST['cash_account_id']??0),$s['currency_code']);funds_record((int)$a['id'],$s['transaction_type']==='برداشت'?'out':'in',$s['amount'],'3000','capital',$id,'capital-payment-'.$id,$s['transaction_date']?:$date);}
 }
}
function finance_settle_debt(int $debt,int $account,$amount,string $date,string $request,string $notes=''): int {
 global $pdo;domain_require('treasury.create');$amount=finance_amount($amount);finance_date($date);
 return finance_atomic(function()use($pdo,$debt,$account,$amount,$date,$request,$notes){
  $q=$pdo->prepare('SELECT id FROM fund_transactions WHERE shop_id=? AND request_key=?');$q->execute([shop_id(),$request]);$existing=$q->fetchColumn();if($existing){$q=$pdo->prepare('SELECT source_id,source_type,account_id,amount,payment_date,notes FROM fund_transactions WHERE id=?');$q->execute([$existing]);$r=$q->fetch();if($r['source_type']!=='debt'||(int)$r['source_id']!==$debt||(int)$r['account_id']!==$account||dec_round($r['amount'])!==$amount||$r['payment_date']!==$date||($r['notes']??'')!==mb_substr($notes,0,1000))throw new InvalidArgumentException('Payment request reused with different data.');return (int)$existing;}
  $q=$pdo->prepare('SELECT * FROM debts WHERE id=? AND shop_id=?'.finance_lock());$q->execute([$debt,shop_id()]);$d=$q->fetch();if(!$d)throw new RuntimeException('Debt not found.',403);$a=funds_account($account,$d['currency_code']);if(finance_is_corrected('debt',$debt))throw new InvalidArgumentException('This debt was cancelled.');if(dec_units($amount)>dec_units($d['remaining_amount']))throw new InvalidArgumentException('Payment exceeds remaining balance.');$receivable=($d['debt_type']??'receivable')!=='payable';$code=$receivable?'1100':'2000';
  if(empty($d['sale_id'])&&!finance_has('debt_opening',$debt,$d['currency_code']))finance_post('debt_opening',$debt,$d['currency_code'],$date,'Declared legacy debt opening',$receivable?[[$code,$d['remaining_amount'],0],['3900',0,$d['remaining_amount']]]:[['3900',$d['remaining_amount'],0],[$code,0,$d['remaining_amount']]]);
  if(!empty($d['sale_id'])&&!finance_has('sale',$d['sale_id'],$d['currency_code'])&&!finance_has('legacy_sale_opening',$d['sale_id'],$d['currency_code']))finance_post('legacy_sale_opening',$d['sale_id'],$d['currency_code'],$date,'Legacy invoice balance opening',[['1100',$d['remaining_amount'],0],['3900',0,$d['remaining_amount']]]);
  $pid=funds_record($account,$receivable?'in':'out',$amount,$code,'debt',$debt,$request,$date,$notes);$remaining=dec_sub($d['remaining_amount'],$amount);$paid=dec_add($d['paid_amount'],$amount);
  $pdo->prepare('UPDATE debts SET paid_amount=?,remaining_amount=?,status=? WHERE id=? AND shop_id=?')->execute([$paid,$remaining,dec_units($remaining)===0?'تسویه':'باز',$debt,shop_id()]);
  $pdo->prepare('INSERT INTO installments (debt_id,amount,payment_date,notes,created_by,currency_code,applied_to_balance,shop_id) VALUES (?,?,?,?,?,?,1,?)')->execute([$debt,$amount,$date,$notes,auth_user()['id'],$d['currency_code'],shop_id()]);
  if($receivable&&!empty($d['sale_id']))$pdo->prepare('UPDATE sales SET paid_amount=?,remaining_amount=? WHERE id=? AND shop_id=?')->execute([$paid,$remaining,$d['sale_id'],shop_id()]);return $pid;
 });
}
function purchase_opening_reviewed(int $purchase): bool {global $pdo;$q=$pdo->prepare('SELECT id FROM purchase_opening_reviews WHERE shop_id=? AND purchase_id=?');$q->execute([shop_id(),$purchase]);return (bool)$q->fetchColumn();}
function finance_review_purchase_opening(int $purchase,$paid,string $note): int {
 global $pdo;domain_require('accounting.approve');domain_require('purchases.approve');$paid=finance_amount($paid,true);if(mb_strlen(trim($note))<10||mb_strlen($note)>1000)throw new InvalidArgumentException('Enter the reviewed opening evidence.');
 return finance_atomic(function()use($pdo,$purchase,$paid,$note){$q=$pdo->prepare('SELECT * FROM inventory_purchases WHERE id=? AND shop_id=?'.finance_lock());$q->execute([$purchase,shop_id()]);$p=$q->fetch();if(!$p)throw new RuntimeException('Purchase unavailable.',403);if(finance_has('purchase',$purchase,$p['currency_code'])||purchase_opening_reviewed($purchase))throw new InvalidArgumentException('This purchase already has accounting entries or a reviewed opening.');$q=$pdo->prepare('SELECT id FROM purchase_returns WHERE shop_id=? AND purchase_id=?');$q->execute([shop_id(),$purchase]);if($q->fetchColumn())throw new InvalidArgumentException('Reconcile pre-existing purchase returns before opening.');$q=$pdo->prepare("SELECT id FROM fund_transactions WHERE shop_id=? AND source_type IN ('purchase','supplier_refund') AND source_id=?");$q->execute([shop_id(),$purchase]);if($q->fetchColumn())throw new InvalidArgumentException('Review existing payment history before opening.');if(dec_units($paid)>dec_units($p['total_amount']))throw new InvalidArgumentException('Verified paid amount exceeds original purchase.');$due=dec_sub($p['total_amount'],$paid);$pdo->prepare('INSERT INTO purchase_opening_reviews (shop_id,purchase_id,verified_paid,verified_payable,review_note,created_by) VALUES (?,?,?,?,?,?)')->execute([shop_id(),$purchase,$paid,$due,$note,auth_user()['id']]);$id=(int)$pdo->lastInsertId();if(dec_units($due)>0)finance_post('purchase_opening',$purchase,$p['currency_code'],date('Y-m-d'),'Verified legacy purchase payable',[['3900',$due,0],['2000',0,$due]]);domain_audit('legacy_purchase_opening_reviewed','purchase',$purchase,['verified_paid'=>$paid,'verified_payable'=>$due,'reference'=>$note,'cash_created'=>false]);return $id;});
}
/** Independent payable/refund balances; do not infer a receipt from a goods return. */
function purchase_balance(array $purchase): array {
 global $pdo;if((int)$purchase['shop_id']!==shop_id())throw new RuntimeException('Purchase branch denied.',403);
 $q=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN source_type='purchase' AND direction='out' THEN amount ELSE 0 END),0) AS paid,COALESCE(SUM(CASE WHEN source_type='supplier_refund' AND direction='in' THEN amount ELSE 0 END),0) AS refund_received FROM fund_transactions WHERE shop_id=? AND source_id=?");$q->execute([shop_id(),$purchase['id']]);$result=$q->fetch();$q=$pdo->prepare('SELECT verified_paid FROM purchase_opening_reviews WHERE shop_id=? AND purchase_id=?');$q->execute([shop_id(),$purchase['id']]);$historical=$q->fetchColumn();$result['paid']=dec_add($result['paid'],$historical===false?0:$historical);$q=$pdo->prepare('SELECT COALESCE(SUM(total_amount),0) FROM purchase_returns WHERE shop_id=? AND purchase_id=?');$q->execute([shop_id(),$purchase['id']]);$result['returned']=dec_round($q->fetchColumn());$remaining=dec_sub(dec_sub($purchase['total_amount'],$result['returned']),$result['paid']);$result['payable']=dec_units($remaining)>0?$remaining:'0.00';$refund=dec_sub(dec_mul($remaining,-1),$result['refund_received']);$result['refund_due']=dec_units($refund)>0?$refund:'0.00';return $result;
}
function finance_pay_purchase(int $purchase,int $account,$amount,string $date,string $request): int {
 global $pdo;domain_require('treasury.create');$amount=finance_amount($amount);return finance_atomic(function()use($pdo,$purchase,$account,$amount,$date,$request){$q=$pdo->prepare('SELECT * FROM inventory_purchases WHERE id=? AND shop_id=?'.finance_lock());$q->execute([$purchase,shop_id()]);$p=$q->fetch();if(!$p)throw new RuntimeException('Purchase unavailable.',403);if(!finance_has('purchase',$purchase,$p['currency_code'])&&!purchase_opening_reviewed($purchase))throw new InvalidArgumentException('Legacy purchases need reviewed opening balances before settlement.');funds_account($account,$p['currency_code']);
  $q=$pdo->prepare("SELECT id FROM fund_transactions WHERE shop_id=? AND request_key=? AND source_type='purchase' AND source_id=?");$q->execute([shop_id(),$request,$purchase]);if($q->fetchColumn())return funds_record($account,'out',$amount,'2000','purchase',$purchase,$request,$date);
  $balance=purchase_balance($p);if(dec_units($amount)>dec_units($balance['payable']))throw new InvalidArgumentException(__t('Payment exceeds purchase balance after returns.','پرداخت از باقی‌داری خرید پس از برگشت بیشتر است.','تادیه له ستنولو وروسته له پاتې پېرود زیاته ده.'));return funds_record($account,'out',$amount,'2000','purchase',$purchase,$request,$date);});
}
function finance_pay_expense(int $expense,int $account,$amount,string $date,string $request): int {
 global $pdo;domain_require('treasury.create');$amount=finance_amount($amount);
 return finance_atomic(function()use($pdo,$expense,$account,$amount,$date,$request){
  $q=$pdo->prepare('SELECT * FROM expenses WHERE id=? AND shop_id=?'.finance_lock());$q->execute([$expense,shop_id()]);$e=$q->fetch();if(!$e||finance_is_corrected('expense',$expense)||!finance_has('expense_payable',$expense,$e['currency_code']))throw new InvalidArgumentException('Only a posted unpaid operating expense can be settled here.');funds_account($account,$e['currency_code']);
  $q=$pdo->prepare("SELECT id FROM fund_transactions WHERE shop_id=? AND request_key=? AND source_type='expense_settlement' AND source_id=?");$q->execute([shop_id(),$request,$expense]);if($q->fetchColumn())return funds_record($account,'out',$amount,'2000','expense_settlement',$expense,$request,$date);
  $q=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM fund_transactions WHERE shop_id=? AND source_type='expense_settlement' AND source_id=? AND direction='out'");$q->execute([shop_id(),$expense]);if(dec_units($amount)>dec_units(dec_sub($e['amount'],$q->fetchColumn())))throw new InvalidArgumentException('Payment exceeds the unpaid expense balance.');
  return funds_record($account,'out',$amount,'2000','expense_settlement',$expense,$request,$date);
 });
}
function finance_close_period(string $through): void {global $pdo;domain_require('accounting.approve');finance_date($through);finance_atomic(function()use($pdo,$through){finance_seed(shop_id());$q=$pdo->prepare('SELECT closed_until FROM financial_periods WHERE shop_id=?'.finance_lock());$q->execute([shop_id()]);$old=$q->fetchColumn();if($old&&$through<$old)throw new InvalidArgumentException('A closed period cannot be reopened here.');$pdo->prepare('UPDATE financial_periods SET closed_until=? WHERE shop_id=?')->execute([$through,shop_id()]);domain_audit('period_closed','period',shop_id(),['closed_until'=>$through]);});}
function finance_in_branch(int $branch,callable $fn){$u=auth_user();if(!$u||!domain_branch_allowed($u,$branch))throw new RuntimeException('Branch denied.',403);$old=$_SESSION['shop_context_id']??null;$_SESSION['shop_context_id']=$branch;try{return $fn();}finally{if($old===null)unset($_SESSION['shop_context_id']);else $_SESSION['shop_context_id']=$old;}}
function funds_transfer(int $source,int $destination,int $destinationBranch,$amount,string $date,string $request): void {
 global $pdo;domain_require('treasury.approve');$origin=shop_id();$dest=domain_branch($destinationBranch);if(!$dest||(int)$dest['business_id']!==domain_business_id()||!domain_can('treasury.approve',auth_user(),$destinationBranch))throw new RuntimeException('Destination access denied.',403);if($source===$destination&&$origin===$destinationBranch)throw new InvalidArgumentException('Choose different accounts.');$amount=finance_amount($amount);
 finance_atomic(function()use($source,$destination,$destinationBranch,$amount,$date,$request,$origin){$a=funds_account($source,null,true);$b=finance_in_branch($destinationBranch,fn()=>funds_account($destination,null,true));if($a['currency_code']!==$b['currency_code'])throw new InvalidArgumentException('Currency conversion requires a separate documented exchange transaction.');
  if($origin===$destinationBranch){$id=funds_record($source,'out',$amount,$b['ledger_code'],'transfer',$destination,$request,$date);return;}
  funds_record($source,'out',$amount,'1400','branch_transfer',$destination,'out-'.$request,$date);finance_in_branch($destinationBranch,fn()=>funds_record($destination,'in',$amount,'1400','branch_transfer',$source,'in-'.$request,$date));
 });
}
function finance_reverse(int $journal,string $date,string $reason): int {
 global $pdo;domain_require('accounting.approve');if(mb_strlen(trim($reason))<3)throw new InvalidArgumentException('Enter a reversal reason.');return finance_atomic(function()use($pdo,$journal,$date,$reason){$q=$pdo->prepare("SELECT * FROM journal_headers WHERE id=? AND shop_id=? AND source_type='manual'".finance_lock());$q->execute([$journal,shop_id()]);$h=$q->fetch();if(!$h)throw new InvalidArgumentException('Only a manual journal may be reversed here. Correct operational documents through their own return/adjustment workflows.');$q=$pdo->prepare('SELECT id FROM journal_headers WHERE reverses_id=?');$q->execute([$journal]);if($q->fetchColumn())throw new InvalidArgumentException('Journal already reversed.');$q=$pdo->prepare('SELECT account_code,debit,credit FROM journal_details WHERE journal_id=? AND shop_id=?');$q->execute([$journal,shop_id()]);$lines=[];foreach($q->fetchAll() as $l)$lines[]=[$l['account_code'],$l['credit'],$l['debit']];$id=finance_post('reversal',$journal,$h['currency_code'],$date,$reason,$lines);$pdo->prepare('UPDATE journal_headers SET reverses_id=? WHERE id=? AND shop_id=?')->execute([$journal,$id,shop_id()]);return $id;});
}
function finance_receive_supplier_refund(int $purchase,int $account,$amount,string $date,string $request): int {
 global $pdo;domain_require('treasury.create');$amount=finance_amount($amount);return finance_atomic(function()use($pdo,$purchase,$account,$amount,$date,$request){$q=$pdo->prepare('SELECT * FROM inventory_purchases WHERE id=? AND shop_id=?'.finance_lock());$q->execute([$purchase,shop_id()]);$p=$q->fetch();if(!$p)throw new RuntimeException('Purchase unavailable.',403);funds_account($account,$p['currency_code']);
  $q=$pdo->prepare("SELECT id FROM fund_transactions WHERE shop_id=? AND request_key=? AND source_type='supplier_refund' AND source_id=?");$q->execute([shop_id(),$request,$purchase]);if($q->fetchColumn())return funds_record($account,'in',$amount,'1300','supplier_refund',$purchase,$request,$date);
  $balance=purchase_balance($p);if(dec_units($amount)>dec_units($balance['refund_due']))throw new InvalidArgumentException(__t('Receipt exceeds the supplier refund due after returns.','دریافت از طلب برگشت پول عرضه‌کننده بیشتر است.','رسید د عرضه کوونکي د ستنولو له طلب زیات دی.'));return funds_record($account,'in',$amount,'1300','supplier_refund',$purchase,$request,$date);
 });
}
